<?php echo form_open(get_uri('payment_complements/'.$complement->id.'/cancel/check'),['id'=>'payment-complement-cancel-status','class'=>'general-form']);echo csrf_field(); ?>
<div class="modal-body"><input type="hidden" name="query_key" value="<?php echo esc($query_key); ?>"><h5>Verificar cancelación del Complemento</h5><div class="alert alert-warning">La solicitud está pendiente o en verificación. El receptor puede contar con hasta 3 días hábiles para aceptar o rechazar.</div><dl><dt>UUID</dt><dd><?php echo esc($complement->uuid); ?></dd><dt>Fecha de solicitud</dt><dd><?php echo esc($requested->format('d/m/Y H:i')); ?></dd><dt>Consulta recomendada</dt><dd><?php echo esc($recommended->format('d/m/Y')); ?></dd><dt>Saldo actual</dt><dd><?php echo(int)$balance['available']; ?> timbres</dd></dl><?php if((int)$balance['available']<1): ?><div class="alert alert-danger">No cuenta con timbres suficientes para consultar.</div><?php endif; ?></div>
<div class="modal-footer"><button type="button" class="btn btn-default" data-bs-dismiss="modal">Cerrar</button><button class="btn btn-primary" <?php echo(int)$balance['available']<1?'disabled':''; ?>>Verificar cancelación</button></div><?php echo form_close(); ?>
